/* HEXA BATTLEGROUNDS upgrade2 — PART 15 OF 22. For databases that already ran supabase/upgrade (match phases); Run in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-movie-0', 'movie', 'battle', 'Emoji Cinema Duel', 'movies', 1, array['duel_pistol']::text[], 'Duel! Name all three films before the other squad does.', '{"scout":{"title":"Film 1","body":"🎈 🏠 👴","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🦇 🌃 🃏","mono":false,"big":true},"intel":{"title":"Film 3","body":"🔥 💧 🤝","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["UP"]},{"label":"Film 2 (Decoder)","accept":["THEDARKKNIGHT","DARKKNIGHT","BATMAN"]},{"label":"Film 3 (Intel)","accept":["RRR"]}]'::jsonb, false, 3, 90, 'Say the emoji out loud.', 'UP: balloons lift a house | THE DARK KNIGHT: bat, night, joker | RRR: fire and water, friendship', null, 25, 'published'), ('battle-movie-1', 'movie', 'battle', 'Emoji Cinema Duel', 'movies', 1, array['duel_pistol']::text[], 'Duel! Name all three films before the other squad does.', '{"scout":{"title":"Film 1","body":"🏴‍☠️ 🌴 💀","mono":false,"big":true},"decoder":{"title":"Film 2","body":"👻 🚫 📞","mono":false,"big":true},"intel":{"title":"Film 3","body":"🌀 💤 🏙️","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["PIRATESOFTHECARIBBEAN","PIRATES"]},{"label":"Film 2 (Decoder)","accept":["GHOSTBUSTERS"]},{"label":"Film 3 (Intel)","accept":["INCEPTION"]}]'::jsonb, false, 3, 90, 'Say the emoji out loud.', 'PIRATES OF THE CARIBBEAN: pirates, islands | GHOSTBUSTERS: who you gonna call | INCEPTION: dreams inside dreams', null, 25, 'published'), ('mission-tech-0', 'techquick', 'mission', 'Tech Quick-Fire', 'tech', 1, array['any','stg','testing','helpdesk','learning','phase2','hexavarsity']::text[], 'Three quick tech questions, one per teammate. One word each.', '{"scout":{"title":"Question 1","body":"Which company''s logo is a bitten fruit?","mono":false,"big":false},"decoder":{"title":"Question 2","body":"Ctrl + Z does what?","mono":false,"big":false},"intel":{"title":"Question 3","body":"Smallest unit of data — a single 0 or 1.","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["APPLE"]},{"label":"Question 2 (Decoder)","accept":["UNDO"]},{"label":"Question 3 (Intel)","accept":["BIT"]}]'::jsonb, false, 3, 200, 'Every answer is one short word.', 'APPLE: Apple | UNDO: Undo | BIT: a bit', null, 25, 'published'), ('mission-tech-1', 'techquick', 'mission', 'Tech Quick-Fire', 'tech', 1, array['any','stg','testing','helpdesk','learning','phase2','hexavarsity']::text[], 'Three quick tech questions, one per teammate. One word each.', '{"scout":{"title":"Question 1","body":"Google''s mobile operating system.","mono":false,"big":false},"decoder":{"title":"Question 2","body":"8 bits make one ___.","mono":false,"big":false},"intel":{"title":"Question 3","body":"HTML = HyperText ___ Language.","mono":false,"big":false}}'::jsonb, '[{"label":"Question 1 (Scout)","accept":["ANDROID"]},{"label":"Question 2 (Decoder)","accept":["BYTE"]},{"label":"Question 3 (Intel)","accept":["MARKUP"]}]'::jsonb, false, 3, 200, 'Every answer is one short word.', 'ANDROID: Android | BYTE: a byte | MARKUP: Markup', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
